ALTER TABLE "customer_order_item" DROP CONSTRAINT "customer_order_item_text_bounds";--> statement-breakpoint
ALTER TABLE "customer_order_item" ADD CONSTRAINT "customer_order_item_text_bounds" CHECK (length("customer_order_item"."target_url") between 1 and 2048 and length("customer_order_item"."anchor_text") between 1 and 200 and length("customer_order_item"."instructions") <= 4000 and ("customer_order_item"."article_text" is null or length("customer_order_item"."article_text") between 1 and 20000) and ("customer_order_item"."writing_brief" is null or length("customer_order_item"."writing_brief") between 1 and 4000));